  const m = VERSION_RE.exec(str);
  if (!m) return null;
  return {
    major: BigInt(m[1]),
    minor: BigInt(m[2]),
    patch: BigInt(m[3]),
    pre: m[4] ? m[4].split('.') : [],
  };
